    "api": {
      "value": "{\"android\": {\"component\": \"@Composable fun ListeningBreakPanel(input: ListeningBreakInput, onStart: (String, String) -> Unit, onCancel: (String) -> Unit, modifier: Modifier = Modifier)\", \"minimum\": \"upstream Reply Compose toolchain\", \"models\": [\"data class ListeningBreakOption(val id: String, val title: String, val detail: String, val isAvailable: Boolean)\", \"data class ListeningBreakInput(val sessionID: String, val title: String, val introduction: String, val options: List<ListeningBreakOption>, val quietNote: String, val footer: String)\"], \"package\": \"com.example.reply.ui.components\"}, \"callbacks\": {\"onCancel\": [\"current input sessionID\"], \"onStart\": [\"current input sessionID\", \"selected option ID\"]}, \"copy\": {\"acknowledgement\": \"I have read the quiet-space note\", \"again\": \"Choose again\", \"cancel\": \"Cancel\", \"errors\": {\"acknowledgement\": \"Confirm the quiet-space note before starting.\", \"both\": \"Choose a soundscape and confirm the quiet-space note.\", \"selection\": \"Choose an available soundscape.\"}, \"ready\": \"Choose a soundscape for your break.\", \"start\": \"Start listening\", \"started\": \"Your listening break is ready.\", \"summaryPrefix\": \"Ready to begin: \"}, \"identity\": \"Complete value equality across all declared input and ordered option fields; no forced identity from the caller.\", \"ios\": {\"component\": \"public struct ListeningBreakPanel: View\", \"initializer\": \"public init(input: ListeningBreakInput, onStart: @escaping (String, String) -> Void, onCancel: @escaping (String) -> Void)\", \"minimum\": \"iOS 14.0\", \"models\": [{\"access\": \"public\", \"conformance\": [\"Equatable\"], \"initializer\": \"public init(id: String, title: String, detail: String, isAvailable: Bool)\", \"name\": \"ListeningBreakOption\", \"properties\": {\"detail\": \"String\", \"id\": \"String\", \"isAvailable\": \"Bool\", \"title\": \"String\"}}, {\"access\": \"public\", \"conformance\": [\"Equatable\"], \"initializer\": \"public init(sessionID: String, title: String, introduction: String, options: [ListeningBreakOption], quietNote: String, footer: String)\", \"name\": \"ListeningBreakInput\", \"properties\": {\"footer\": \"String\", \"introduction\": \"String\", \"options\": \"[ListeningBreakOption]\", \"quietNote\": \"String\", \"sessionID\": \"String\", \"title\": \"String\"}}], \"module\": \"AlertToast\"}, \"version\": 1}",
      "unit": "string"
    },
    "input_domain": {
      "value": "Accept valid caller inputs with a nonempty sessionID, at least one available option, unique ASCII option IDs matching [A-Za-z0-9_-]+, nonempty copy, and caller-preserved option order; the component owns no audio engine or network operation.",
      "unit": "string"
    },
    "identifiers": {
      "value": "Expose stable identifiers listening.canvas, listening.title, listening.introduction, listening.note, listening.acknowledge, listening.status, listening.primary, listening.cancel, listening.footer, listening.error and listening.summary; each option control uses listening.option.<id>.",
      "unit": "string"
    },
    "semantics": {
      "value": "Give each option one native button with accessible label title + \" — \" + detail and a selected trait that matches its local selection; the acknowledgement is one labeled native switch with its real Boolean value.",
      "unit": "string"
    },
    "selection": {
      "value": "Selecting an available option exclusively selects its ID; selecting it again preserves that selection, changing to another available option replaces it, and unavailable options remain disabled and never selectable.",
      "unit": "string"
    },
    "validation": {
      "value": "While editing, a successful Start listening activation validates both an available selected option and acknowledgement on; unmet conditions leave editing active and show the applicable exact error text defined in api-contract.json without emitting onStart or onCancel. Exact error copy: {\"acknowledgement\": \"Confirm the quiet-space note before starting.\", \"both\": \"Choose a soundscape and confirm the quiet-space note.\", \"selection\": \"Choose an available soundscape.\"}",
      "unit": "string"
    },
    "cancel": {
      "value": "Cancel remains enabled in every state; each activation invokes onCancel(current sessionID) once and returns to initial editing for that same input, including repeated Cancel activations with no choices.",
      "unit": "string"
    },
    "edit_error": {
      "value": "Changing either editing choice clears the visible validation error; turning acknowledgement off is allowed while editing and does not clear the selected option.",
      "unit": "string"
    },
    "replacement": {
      "value": "Any unequal full input replacement resets selection, acknowledgement, validation and started state before the replacement is rendered, even when sessionID and option IDs are unchanged; rendering an equal input preserves local state and neither case emits callbacks.",
      "unit": "string"
    },
    "bridge_boundary": {
      "value": "Keep the component identity and business logic in production: the supplied bridges adapt fixture values and real callback arguments only, and neither bridge may force identity changes, supply local product state, or synthesize callback outcomes.",
      "unit": "string"
    },
    "colors": {
      "value": "Use exact opaque sRGB colors from reference.json: canvas behind the column and Cancel; option/selectedOption/unavailableOption on option surfaces; primary and primaryInk on the primary button; title on the heading; body on introduction, note, available option titles, acknowledgement, status, summary and Cancel text; muted on option details, unavailable option titles and footer; error on error text; border on every option outline; use no shadows, gradients or translucency.",
      "unit": "string"
    },
    "spacing": {
      "value": "Use a single column filling its parent content width (the observer offers total width minus its own 32-unit horizontal inset), with 20 native units of internal canvas padding, 12 units between major blocks and options, 12-unit option and action corner radii, 16-unit option/action horizontal padding and 12-unit vertical padding, and a 1-unit option border; each title/detail option pair has a 4-unit internal gap and actions fill the available column width.",
      "unit": "string"
    },
    "typography": {
      "value": "Use platform-scaled system text at the base sizes and weights in reference.json: title 24 semibold, introduction/note/option title 16 regular except option title semibold, option detail/footer 14 regular, status/error/summary 16 regular, and action text 16 semibold.",
